import type { CliEnvelope } from './envelope';
import type { BrowserOpenResult } from './browser';
import {
  isServerUnavailableReason,
  type ServerUnavailableReason,
} from './serverUnavailable';
import {
  GUIDANCE_VERIFIER_ERROR_REASONS,
  type GuidanceVerifierErrorReason,
} from '../types/guidance-verifier';

export type { ServerUnavailableReason } from './serverUnavailable';

export type DesignContextKind =
  'arena' | 'pinterest' | 'reference' | 'unsupported' | 'website';

export type VariantContextKind = 'image' | 'variant' | 'video' | 'website';
export type VariantContextMetadata = {
  contextKinds?: VariantContextKind[];
  contextImageCount?: number;
  referencePageCount?: number;
  referenceVideoCount?: number;
};

export type BrowserMetadata = {
  browserAction?: BrowserOpenResult['action'];
  browserReason?: BrowserOpenResult['reason'];
};

const COMPLETED_VERIFICATION_STATUSES = ['pass', 'fail', 'blocked'] as const;
type CompletedVerificationStatus =
  (typeof COMPLETED_VERIFICATION_STATUSES)[number];
export type VerificationOutcome =
  CompletedVerificationStatus | GuidanceVerifierErrorReason;
export type VerificationMetadata = {
  verificationOutcome?: VerificationOutcome;
  verificationCheckCount?: number;
  verificationDurationMs?: number;
};

const isCompletedVerificationStatus = (
  value: unknown,
): value is CompletedVerificationStatus =>
  typeof value === 'string' &&
  (COMPLETED_VERIFICATION_STATUSES as readonly string[]).includes(value);

const isGuidanceVerifierErrorReason = (
  value: unknown,
): value is GuidanceVerifierErrorReason =>
  typeof value === 'string' &&
  (GUIDANCE_VERIFIER_ERROR_REASONS as readonly string[]).includes(value);

const isNonNegativeDuration = (value: unknown): value is number =>
  typeof value === 'number' && Number.isFinite(value) && value >= 0;

const verificationOutcomeForReport = (
  report: Record<string, unknown>,
): VerificationOutcome | undefined => {
  if (
    report.execution === 'completed' &&
    isCompletedVerificationStatus(report.status)
  ) {
    return report.status;
  }
  if (
    report.execution === 'error' &&
    isGuidanceVerifierErrorReason(report.reason)
  ) {
    return report.reason;
  }
  return undefined;
};

const recordOf = (value: unknown): Record<string, unknown> =>
  value !== null && typeof value === 'object'
    ? (value as Record<string, unknown>)
    : {};

export const verificationMetadataForEnvelope = (
  envelope: CliEnvelope,
): VerificationMetadata => {
  if (envelope.command !== 'context.verify') return {};
  const report = recordOf(envelope.ok ? envelope.data : envelope.error.details);
  const verificationOutcome = verificationOutcomeForReport(report);
  const verificationCheckCount = Array.isArray(report.checks)
    ? report.checks.length
    : undefined;
  const verificationDurationMs = isNonNegativeDuration(report.durationMs)
    ? report.durationMs
    : undefined;
  return {
    ...(verificationOutcome !== undefined ? { verificationOutcome } : {}),
    ...(verificationCheckCount !== undefined ? { verificationCheckCount } : {}),
    ...(verificationDurationMs !== undefined ? { verificationDurationMs } : {}),
  };
};

export const browserMetadataForEnvelope = (
  envelope: CliEnvelope,
): BrowserMetadata => {
  if (envelope.command !== 'open') return {};
  const browser = recordOf(
    envelope.ok
      ? recordOf(envelope.data).browser
      : recordOf(envelope.error.details).browser,
  );
  if (
    (browser.action === 'launch_requested' &&
      browser.reason === 'interactive_open') ||
    (browser.action === 'skipped' && browser.reason === 'no_browser_flag') ||
    (browser.action === 'launch_failed' && browser.reason === 'launcher_error')
  ) {
    return { browserAction: browser.action, browserReason: browser.reason };
  }
  return {};
};

export const serverUnavailableReasonForEnvelope = (
  envelope: CliEnvelope,
): ServerUnavailableReason | undefined => {
  if (envelope.ok || envelope.error.code !== 'SERVER_UNAVAILABLE') {
    return undefined;
  }
  const reason = recordOf(envelope.error.details).serverUnavailableReason;
  return isServerUnavailableReason(reason) ? reason : undefined;
};

export const designContextKindForEnvelope = (
  envelope: CliEnvelope,
): DesignContextKind | undefined => {
  if (envelope.command === 'evidence.capture') return 'website';
  if (envelope.command !== 'reference.fetch') return undefined;

  const payload = envelope.ok
    ? recordOf(envelope.data)
    : recordOf(envelope.error.details);
  if (payload.provider === 'pinterest') return 'pinterest';
  if (payload.provider === 'arena') return 'arena';
  if (payload.status === 'unsupported') return 'unsupported';
  return 'reference';
};

const flagValue = (args: string[], flag: string): string | undefined => {
  const index = args.indexOf(flag);
  if (index >= 0) return args[index + 1];
  const inlinePrefix = `${flag}=`;
  return args
    .find((arg) => arg.startsWith(inlinePrefix))
    ?.slice(inlinePrefix.length);
};

const hasFlag = (args: string[], flag: string): boolean =>
  args.includes(flag) || args.some((arg) => arg.startsWith(`${flag}=`));

const jsonArrayFlagCount = (args: string[], flag: string): number => {
  const value = flagValue(args, flag);
  if (value === undefined) return 0;
  try {
    const parsed = JSON.parse(value) as unknown;
    return Array.isArray(parsed) ? parsed.length : 0;
  } catch {
    return 0;
  }
};

export const variantContextMetadataForArgs = (
  command: string,
  args: string[],
): VariantContextMetadata => {
  if (command !== 'variants' || args[0] !== 'start') return {};
  const contextImageCount = jsonArrayFlagCount(args, '--context-images');
  const referencePageCount = jsonArrayFlagCount(args, '--reference-pages');
  const referenceVideoCount = jsonArrayFlagCount(args, '--reference-videos');
  const contextKinds: VariantContextKind[] = [];
  if (contextImageCount > 0) contextKinds.push('image');
  if (hasFlag(args, '--target')) contextKinds.push('variant');
  if (referenceVideoCount > 0) contextKinds.push('video');
  if (referencePageCount > 0) contextKinds.push('website');
  return {
    ...(contextKinds.length > 0 ? { contextKinds } : {}),
    ...(contextImageCount > 0 ? { contextImageCount } : {}),
    ...(referencePageCount > 0 ? { referencePageCount } : {}),
    ...(referenceVideoCount > 0 ? { referenceVideoCount } : {}),
  };
};
